<div x-data="storySpeech(@js(route('audio.index',$story)))">
<template x-teleport="body"><dialog x-ref="speechDialog" class="image-picker-dialog reference-dialog rounded-xl border bg-white p-5 text-stone-900 shadow-xl dark:bg-stone-900 dark:text-stone-100" @click="if($event.target===$el)$el.close()" @close="stopListening();player.stop();$el.querySelectorAll('audio').forEach(a=>a.pause())">
<div class="flex max-h-[80dvh] flex-col"><header class="flex items-center justify-between gap-4 border-b px-6 py-4"><h2 class="font-serif text-xl">Generate description speech</h2><button type="button" class="btn-secondary" @click="$refs.speechDialog.close()">Close</button></header>
<div class="min-h-0 space-y-5 overflow-y-auto px-6 py-5"><label class="field">Text to read<textarea x-model="text" maxlength="5000" rows="4"></textarea></label>
<div class="grid grid-cols-2 gap-3"><label class="field">Model<select x-model="model" @change="selectModel()"><template x-for="m in models" :key="m.id"><option :value="m.id" x-text="m.name"></option></template></select></label><label class="field">Voice<select x-model="voice"><template x-for="v in selected?.supported_voices || []" :key="v"><option :value="v" x-text="v"></option></template></select></label></div>
<template x-if="model.startsWith('google/')"><div class="space-y-3"><label class="field">Delivery instructions<textarea x-model="instructions" maxlength="1000" placeholder="Calm, mysterious, unhurried…"></textarea></label><label class="field">Temperature<input type="number" min="0" max="2" step="0.1" x-model="temperature"></label></div></template>
<label class="field" x-show="model.startsWith('heygen/')">Language (optional code)<input x-model="language" maxlength="10" placeholder="en"></label>
<p class="text-xs" x-show="model.startsWith('elevenlabs/')">Use inline tags such as [whispering] in the spoken text for expressive delivery.</p>
<p x-show="error" x-text="error" class="text-sm text-red-600" role="alert"></p>
<template x-for="job in jobs.filter(j=>j.source_text===source)" :key="job.id"><div class="rounded-lg border p-4 text-xs"><span x-text="job.model+' · '+job.status"></span><p x-show="job.error" x-text="job.error"></p><audio x-show="job.sound_id" controls preload="none" :src="sounds.find(s=>s.id===job.sound_id)?.url" class="mt-2 w-full"></audio></div></template>
</div><footer class="flex justify-end gap-3 border-t px-6 py-4"><button type="button" class="btn-secondary speech-preview-button" @click="listen(source)" :disabled="!speechFor(source)" :aria-pressed="isListening(source)" x-text="isListening(source)?'Stop':'Listen'"></button><button type="button" class="btn-primary" :disabled="busy || !voice || !text.trim()" @click="generate()" x-text="busy?'Queuing…':'Generate speech'"></button></footer></div>
</dialog></template></div>
